import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.B8TleWq7.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"reference/faq.md","filePath":"reference/faq.md"}'),s={name:"reference/faq.md"};function i(n,e,d,c,h,l){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="setup-and-workflow" tabindex="-1">Setup and workflow <a class="header-anchor" href="#setup-and-workflow" aria-label="Permalink to &quot;Setup and workflow&quot;">​</a></h2><h3 id="why-isn-t-keel-installed-with-rojo-wally-or-npm" tabindex="-1">Why isn&#39;t Keel installed with Rojo, Wally or npm? <a class="header-anchor" href="#why-isn-t-keel-installed-with-rojo-wally-or-npm" aria-label="Permalink to &quot;Why isn&#39;t Keel installed with Rojo, Wally or npm?&quot;">​</a></h3><p>Keel is built for Roblox Studio&#39;s built-in <strong>Script Sync</strong> and GitHub only. Keel finds its own files at fixed paths (<code>ReplicatedStorage.Keel</code>, <code>ServerScriptService.KeelServer</code>), and server code must never reach clients, which a package folder cannot guarantee. <code>tools/keel.js</code> copies the files to the right places and records their hashes.</p><h3 id="can-i-edit-keel-inside-my-game" tabindex="-1">Can I edit Keel inside my game? <a class="header-anchor" href="#can-i-edit-keel-inside-my-game" aria-label="Permalink to &quot;Can I edit Keel inside my game?&quot;">​</a></h3><p>No. Owned files are replaced on every update, and <code>update</code> refuses (listing the files) if any were edited. Make the change in the Keel repo, tag a version, and update the game. See <a href="/Keel-Docs/guides/releasing-keel">Releasing Keel</a>.</p><h3 id="how-do-i-know-which-version-a-game-has" tabindex="-1">How do I know which version a game has? <a class="header-anchor" href="#how-do-i-know-which-version-a-game-has" aria-label="Permalink to &quot;How do I know which version a game has?&quot;">​</a></h3><p><code>node tools/keel.js status</code>, or read <code>keel.json</code>. Set the <code>Version</code> attribute on <code>ReplicatedStorage</code> and every client shows a small <code>v&lt;version&gt;</code> label, so bug reports name their build.</p><h3 id="what-does-update-touch" tabindex="-1">What does <code>update</code> touch? <a class="header-anchor" href="#what-does-update-touch" aria-label="Permalink to &quot;What does `update` touch?&quot;">​</a></h3><p>Only owned files. Starter files (<code>Shared/</code>, <code>Server/</code>, <code>ReplicatedFirst/</code>, <code>Boot/</code>, <code>CLAUDE.md</code>, <code>Docs/Start Here.md</code>, ...) are copied once by <code>new</code> and are yours. See <a href="/Keel-Docs/getting-started/what-gets-created">What gets created</a>.</p><h3 id="can-script-sync-be-connected-automatically" tabindex="-1">Can Script Sync be connected automatically? <a class="header-anchor" href="#can-script-sync-be-connected-automatically" aria-label="Permalink to &quot;Can Script Sync be connected automatically?&quot;">​</a></h3><p>No. Studio has no way to script Script Sync&#39;s &quot;Sync with Directory&quot;, and the connections are not saved in the place file, so a pre-connected template place does not work either. The <strong>Keel Setup</strong> plugin creates the Folders and attributes and lists the six connects to make by hand. See <a href="/Keel-Docs/getting-started/connect-studio">Connect Roblox Studio</a>.</p><h3 id="a-folder-i-created-isn-t-showing-in-studio" tabindex="-1">A folder I created isn&#39;t showing in Studio. <a class="header-anchor" href="#a-folder-i-created-isn-t-showing-in-studio" aria-label="Permalink to &quot;A folder I created isn&#39;t showing in Studio.&quot;">​</a></h3><p>A folder holding only a <code>.gitkeep</code> does not appear in Studio: Script Sync ignores non-script files. It appears when you add its first <code>.luau</code> file.</p><h2 id="code" tabindex="-1">Code <a class="header-anchor" href="#code" aria-label="Permalink to &quot;Code&quot;">​</a></h2><h3 id="where-does-a-new-system-go" tabindex="-1">Where does a new system go? <a class="header-anchor" href="#where-does-a-new-system-go" aria-label="Permalink to &quot;Where does a new system go?&quot;">​</a></h3><p>A server system is a <strong>Service</strong> in <code>Server/Services/</code> (or <code>Server/Systems/</code> for clock-driven work); a client system is a <strong>Controller</strong> in <code>Client/Controllers/</code>. Behaviour shared by players, NPCs and world objects is a <strong>component</strong> in <code>Components/</code>. See <a href="/Keel-Docs/guides/architecture">Architecture</a>.</p><h3 id="why-can-t-i-send-a-message-from-the-client" tabindex="-1">Why can&#39;t I send a message from the client? <a class="header-anchor" href="#why-can-t-i-send-a-message-from-the-client" aria-label="Permalink to &quot;Why can&#39;t I send a message from the client?&quot;">​</a></h3><p>A client may send a message only if it declares a <code>Rate</code>. A message without one is server-to-client only. See <a href="/Keel-Docs/guides/networking">Networking</a>.</p><h3 id="why-is-my-init-erroring-with-init-waited" tabindex="-1">Why is my <code>Init</code> erroring with &quot;Init waited&quot;? <a class="header-anchor" href="#why-is-my-init-erroring-with-init-waited" aria-label="Permalink to &quot;Why is my `Init` erroring with &quot;Init waited&quot;?&quot;">​</a></h3><p><code>Init</code> must not wait or call other modules; that rule is what makes the boot order safe. Move the waiting work into <code>Start</code>, or into <code>task.spawn</code>.</p><h3 id="does-start-wait-for-my-dependencies-start" tabindex="-1">Does <code>Start</code> wait for my dependencies&#39; <code>Start</code>? <a class="header-anchor" href="#does-start-wait-for-my-dependencies-start" aria-label="Permalink to &quot;Does `Start` wait for my dependencies&#39; `Start`?&quot;">​</a></h3><p>No. Starts are launched in dependency order, each in its own thread, so a <code>Start</code> that waits never holds back the others. If you need something a dependency sets up in its <code>Start</code>, wait for a Signal it fires.</p><h3 id="where-do-i-put-secret-data-drop-tables-odds" tabindex="-1">Where do I put secret data (drop tables, odds)? <a class="header-anchor" href="#where-do-i-put-secret-data-drop-tables-odds" aria-label="Permalink to &quot;Where do I put secret data (drop tables, odds)?&quot;">​</a></h3><p><code>Server/Defs/</code>. Anything in <code>Shared/Defs/</code> is sent to every client.</p><h3 id="how-do-i-change-a-number-without-republishing" tabindex="-1">How do I change a number without republishing? <a class="header-anchor" href="#how-do-i-change-a-number-without-republishing" aria-label="Permalink to &quot;How do I change a number without republishing?&quot;">​</a></h3><p>Put it in <code>Server/Defs</code> and list its key in <code>Server/Defs/LiveKeys</code>, then set a ConfigService value. See <a href="/Keel-Docs/guides/defs#live-tuning-server-only-defs">Defs: live tuning</a>. Values clients display need a publish.</p><h3 id="why-doesn-t-my-change-to-a-player-s-data-reach-the-client" tabindex="-1">Why doesn&#39;t my change to a player&#39;s data reach the client? <a class="header-anchor" href="#why-doesn-t-my-change-to-a-player-s-data-reach-the-client" aria-label="Permalink to &quot;Why doesn&#39;t my change to a player&#39;s data reach the client?&quot;">​</a></h3><p>Write replicated state with <code>Replica.Set</code>. A direct write to the data table is saved but not sent. See <a href="/Keel-Docs/guides/state-and-replica">State and Replica</a>.</p><h3 id="why-can-t-i-save-owns-vip" tabindex="-1">Why can&#39;t I save &quot;owns VIP&quot;? <a class="header-anchor" href="#why-can-t-i-save-owns-vip" aria-label="Permalink to &quot;Why can&#39;t I save &quot;owns VIP&quot;?&quot;">​</a></h3><p>Free trials and refunds end game-pass ownership without any event. Ask Roblox each time it matters with <code>Purchases.OwnsPass</code>. See <a href="/Keel-Docs/guides/purchases#game-passes-ask-never-remember">Purchases</a>.</p><h3 id="does-keel-work-with-streamingenabled" tabindex="-1">Does Keel work with StreamingEnabled? <a class="header-anchor" href="#does-keel-work-with-streamingenabled" aria-label="Permalink to &quot;Does Keel work with StreamingEnabled?&quot;">​</a></h3><p>Yes. Keel assumes it is on (client components attach when a tagged model streams in and clean up when it streams out) and also works with it off.</p><h3 id="are-there-optional-add-ons-kits" tabindex="-1">Are there optional add-ons (&quot;Kits&quot;)? <a class="header-anchor" href="#are-there-optional-add-ons-kits" aria-label="Permalink to &quot;Are there optional add-ons (&quot;Kits&quot;)?&quot;">​</a></h3><p>They are planned (<code>ReplicatedStorage/Kits</code>, <code>ServerScriptService/KitsServer</code>), but none are built yet.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><h3 id="how-many-network-messages-can-a-game-have" tabindex="-1">How many network messages can a game have? <a class="header-anchor" href="#how-many-network-messages-can-a-game-have" aria-label="Permalink to &quot;How many network messages can a game have?&quot;">​</a></h3><p>256, including Net&#39;s internal <code>Keel.Ready</code>. The 257th definition errors, because Packet ids are one byte.</p><h3 id="how-big-can-an-unreliable-message-be" tabindex="-1">How big can an unreliable message be? <a class="header-anchor" href="#how-big-can-an-unreliable-message-be" aria-label="Permalink to &quot;How big can an unreliable message be?&quot;">​</a></h3><p>Payloads over 900 bytes error at the sender.</p><h3 id="how-often-does-keel-autosave" tabindex="-1">How often does Keel autosave? <a class="header-anchor" href="#how-often-does-keel-autosave" aria-label="Permalink to &quot;How often does Keel autosave?&quot;">​</a></h3><p>Every 60 seconds, plus a save on leave and on shutdown.</p><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><h3 id="how-do-i-run-keel-s-tests" tabindex="-1">How do I run Keel&#39;s tests? <a class="header-anchor" href="#how-do-i-run-keel-s-tests" aria-label="Permalink to &quot;How do I run Keel&#39;s tests?&quot;">​</a></h3><p>In a playtest, from the server command bar: <code>require(game.ServerScriptService.KeelServer.Tests.Runner).Run()</code>. See <a href="/Keel-Docs/guides/unit-tests">Unit tests</a>.</p><h3 id="red-errors-scrolled-past-during-the-tests-did-they-fail" tabindex="-1">Red errors scrolled past during the tests. Did they fail? <a class="header-anchor" href="#red-errors-scrolled-past-during-the-tests-did-they-fail" aria-label="Permalink to &quot;Red errors scrolled past during the tests. Did they fail?&quot;">​</a></h3><p>Some tests break things on purpose. Only <code>[FAIL]</code> lines count, and the run ends with <code>[Tests] N passed, M failed</code>.</p>',47)])])}const m=a(s,[["render",i]]);export{p as __pageData,m as default};
